// ZT17, BR-026, FR-056, FR-079, FR-093: a report holds what its list holds for the same company, scope, period and state, with no
// monetary difference, and pending payments are not paid. Every report here is requested, generated by the worker and downloaded
// through its real route; each section compares the file with the routes and rows it comes from, under the same actor, with its
// scope limit, the filter and format flags its catalogue entry declares, and the confidential fields it must not carry. Other files
// hold what they already prove: expense-reports (the five section 11 outputs), confirmation.api (list parity per view) and
// correction.api (corrections in force). Synthetic data only.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { uniq } from '../../../../../db/tests/fixtures.js';
import { type Company, type Harness, startHarness, type TestActor } from '../../test/harness.js';
import type { PermissionKey } from '../access/baseline.js';
import { prepareReady, releaseNaming } from '../expense/payment.fixtures.js';
import { mondayAfter } from '../workflow/leave-tasks.fixtures.js';
import { REPORTS } from './catalogue.js';
import { csvContext, csvTable } from './csv.fixtures.js';
import { processReportQueue } from './service.js';

let h: Harness;
let A: Company;
let B: Company;
let hr: TestActor;

interface Person {
  id: string;
  code: string;
}

/** Every cell of a report CSV line (every cell is quoted; quotes are doubled). */
const cells = (line: string) => [...line.matchAll(/"((?:[^"]|"")*)"/g)].map((m) => m[1]!.replace(/""/g, '"'));
const money = (value: string | number | null | undefined) => (value === null || value === undefined || value === '' ? '' : Number(value).toFixed(2));
const sum = (values: (string | number | null | undefined)[]) => values.reduce<number>((total, v) => total + Number(v || 0), 0).toFixed(2);

/** Requests, generates and downloads a report: its rows by column header, its raw body, and that the file counts what it holds. */
async function generated(a: TestActor, reportCode: string, filters: object = {}) {
  const requested = await h.call(a, 'POST', '/v1/reports', { reportCode, filters });
  expect(requested.statusCode, requested.body).toBe(202);
  await processReportQueue(h.pool);
  const id = requested.json().id as string;
  const file = await h.call(a, 'GET', `/v1/reports/${id}/download`);
  expect(file.statusCode, file.body).toBe(200);
  const [header, ...lines] = csvTable(file.body).trimEnd().split('\r\n').map(cells);
  const rows = lines.map((line) => Object.fromEntries(header!.map((column, i) => [column, line[i]!])));
  // FR-056 the filter snapshot and the count of what was exported; catalogue.ts the columns and nothing else.
  expect(header).toEqual(REPORTS[reportCode]!.columns.map((c) => c.header));
  expect((await h.call(a, 'GET', `/v1/reports/${id}`)).json()).toMatchObject({ state: 'COMPLETED', reportCode, format: 'CSV', filters, rowCount: rows.length });
  expect(Number(csvContext(file.body).Rows)).toBe(rows.length);
  return { rows, body: file.body };
}

const refusal = async (a: TestActor, reportCode: string, filters: object, format?: string) => {
  const res = await h.call(a, 'POST', '/v1/reports', { reportCode, filters, ...(format ? { format } : {}) });
  return [res.statusCode, res.json().error];
};

async function person(overrides: Record<string, unknown> = {}, status = 'ACTIVE_CONFIRMED'): Promise<Person> {
  const res = await h.call(hr, 'POST', '/v1/employees', h.newEmployeeBody(A, overrides));
  expect(res.statusCode, res.body).toBe(201);
  const e = res.json();
  await h.setStatus(A, e.id, status);
  return { id: e.id, code: e.employeeCode };
}

beforeAll(async () => {
  h = await startHarness();
  A = await h.makeCompany();
  B = await h.makeCompany();
  hr = await h.actor(A, 'HR_ADMINISTRATOR');
});

afterAll(async () => {
  await h?.stop();
});

describe('catalogue flags of the reports this gate reconciles (FR-056; catalogue.ts)', () => {
  const period = { from: '2026-01-01', to: '2026-12-31' };
  const someId = '00000000-0000-4000-8000-000000000001';

  // Each report accepts only the filters it applies: a filter it would ignore must be refused, or the file claims a selection it did not make (BR-026).
  it.each<[string, object, object]>([
    ['LEAVE_REGISTER', period, { status: 'APPROVED' }],
    ['LEAVE_REGISTER', period, { employeeId: someId }],
    ['LEAVE_REGISTER', period, { departmentId: someId }],
    ['ATTENDANCE_REGISTER', period, { projectId: someId }],
    ['ATTENDANCE_REGISTER', period, { joinedFrom: '2026-01-01' }],
    ['ATTENDANCE_REGISTER', period, { view: 'ALL' }],
    ['CONFIRMATION_DUE', {}, { status: 'OPEN' }],
    ['CONFIRMATION_DUE', {}, { employeeId: someId }],
    ['CONFIRMATION_DUE', {}, { search: 'x' }],
    ['EXPENSE_REGISTER', period, { status: 'APPROVED' }],
    ['EXPENSE_REGISTER', period, { employeeId: someId }],
    ['EXPENSE_REGISTER', period, { departmentId: someId }],
    ['INCREMENT_HISTORY', period, { status: 'APPROVED' }],
    ['INCREMENT_HISTORY', period, { employeeId: someId }],
    ['INCREMENT_HISTORY', period, { basis: 'MONTHLY_GROSS' }],
  ])('%s with %o refuses the undeclared filter %o', async (code, base, extra) => {
    const a = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['expense.export.operational', 'increment.export.salary', 'increment.history_read.salary'] });
    expect(await refusal(a, code, { ...base, ...extra })).toEqual([422, 'FILTER_NOT_SUPPORTED']);
  });

  it('none of them is generated as XLSX, as the catalogue says; a period is required exactly where it is declared', async () => {
    const a = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['expense.export.operational', 'increment.export.salary', 'increment.history_read.salary'] });
    const shown = Object.fromEntries(((await h.call(a, 'GET', '/v1/reports/catalogue')).json().items as { code: string; requiresPeriod: boolean; formats?: string[] }[]).map((r) => [r.code, r]));
    for (const [code, needsPeriod] of [['LEAVE_REGISTER', true], ['ATTENDANCE_REGISTER', true], ['CONFIRMATION_DUE', false], ['EXPENSE_REGISTER', true], ['INCREMENT_HISTORY', true]] as const) {
      expect(shown[code]!.formats, code).toBeUndefined();
      expect(shown[code]!.requiresPeriod, code).toBe(needsPeriod);
      expect(await refusal(a, code, needsPeriod ? period : {}, 'XLSX'), code).toEqual([422, 'FORMAT_NOT_SUPPORTED']);
      if (needsPeriod) {
        expect(await refusal(a, code, {}), code).toEqual([422, 'PERIOD_REQUIRED']);
        expect(await refusal(a, code, { from: '2026-02-01', to: '2026-01-31' }), code).toEqual([422, 'INVALID_PERIOD']);
      }
    }
  });
});

describe('LEAVE_REGISTER (FR-056; BR-026; ZT17)', () => {
  const week1 = mondayAfter(40);
  const day = (n: number) => new Date(Date.parse(`${week1}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10);
  const PERIOD = { from: day(1), to: day(7) }; // Tuesday of week 1 to Monday of week 2
  const PRIVATE_REASON = 'Private medical detail zq7 (synthetic)';
  let people: Person[];
  let inEng: Person;
  let inEng2: Person;
  let inFin: Person;
  let manager: TestActor;

  beforeAll(async () => {
    const policies = (await h.call(hr, 'GET', '/v1/leave/policies')).json().items as { id: string; version: number; state: string }[];
    for (const p of policies.filter((x) => x.state === 'DRAFT')) expect((await h.call(hr, 'POST', `/v1/leave/policies/${p.id}/activate`, { expectedVersion: p.version })).statusCode).toBe(200);
    const boss = await person();
    manager = await h.actor(A, 'REPORTING_MANAGER', { employeeId: boss.id });
    inEng = await person();
    inEng2 = await person();
    inFin = await person({ departmentId: A.financeDept });
    people = [inEng, inEng2, inFin];
    for (const p of people) expect((await h.call(hr, 'POST', `/v1/employees/${p.id}/manager`, { managerEmployeeId: boss.id, effectiveFrom: '2026-01-05' })).statusCode).toBe(200);
    const as = async (p: Person) => h.actor(A, 'EMPLOYEE', { employeeId: p.id });
    const [eng, eng2, fin] = [await as(inEng), await as(inEng2), await as(inFin)];
    const ask = async (a: TestActor, startDate: string, endDate: string) => {
      const res = await h.call(a, 'POST', '/v1/leave/requests', { leaveType: 'UNPAID', startDate, endDate, reason: PRIVATE_REASON });
      expect(res.statusCode, res.body).toBe(201);
      return res.json().requestId as string;
    };
    const decide = async (requestId: string, decision: string) => {
      const tx = (await h.one<{ transaction_id: string }>(`select transaction_id from leave_request where id = $1`, [requestId])).transaction_id;
      const task = ((await h.call(manager, 'GET', '/v1/leave/tasks')).json().items as { taskId: string; transactionId: string }[]).find((t) => t.transactionId === tx)!;
      const res = await h.call(manager, 'POST', `/v1/leave/tasks/${task.taskId}/decision`, { decision, reason: 'Decided (synthetic)', idempotencyKey: uniq('parity-leave-') });
      expect(res.statusCode, res.body).toBe(200);
    };
    await decide(await ask(eng, day(0), day(2)), 'APPROVE'); // overlaps the period's start: Monday to Wednesday of week 1
    await ask(eng, day(7), day(7)); // the period's last day, waiting
    await decide(await ask(eng2, day(1), day(1)), 'REJECT'); // the period's first day, rejected
    expect((await h.call(eng2, 'POST', `/v1/leave/requests/${await ask(eng2, day(3), day(3))}/withdraw`)).statusCode).toBe(200);
    await ask(fin, day(2), day(4)); // another department, waiting
    await ask(fin, day(0), day(0)); // the day before the period
    await ask(eng, day(14), day(14)); // after the period
  });

  /** The requests the per-employee list shows that overlap the period, as the report's rows. */
  async function listed(a: TestActor, among: Person[]) {
    const rows: Record<string, string>[] = [];
    for (const p of among) {
      const items = (await h.call(a, 'GET', `/v1/employees/${p.id}/leave-requests`)).json().items as { leaveType: string; startDate: string; endDate: string; units: string; state: string }[];
      for (const r of items.filter((x) => x.startDate <= PERIOD.to && x.endDate >= PERIOD.from)) {
        rows.push({ 'Employee code': p.code, 'Leave type': r.leaveType, 'Start date': r.startDate, 'End date': r.endDate, Days: r.units, State: r.state });
      }
    }
    return rows;
  }
  const byKey = (rows: Record<string, string>[]) => [...rows].sort((x, y) => `${x['Employee code']}${x['Start date']}`.localeCompare(`${y['Employee code']}${y['Start date']}`));

  it('holds exactly the requests of the list that overlap the period, in every state, with the same facts and days', async () => {
    const { rows } = await generated(hr, 'LEAVE_REGISTER', PERIOD);
    expect(byKey(rows)).toEqual(byKey(await listed(hr, people)));
    const inPeriod = await h.one<{ n: number; days: string }>(
      `select count(*)::int as n, sum(requested_units)::text as days from leave_request where company_id = $1 and start_date <= $3::date and end_date >= $2::date`,
      [A.id, PERIOD.from, PERIOD.to],
    );
    expect(rows).toHaveLength(inPeriod.n);
    expect(sum(rows.map((r) => r.Days))).toBe(money(inPeriod.days));
    expect(rows.map((r) => r.State).sort()).toEqual(['APPROVED', 'REJECTED', 'SUBMITTED', 'SUBMITTED', 'WITHDRAWN']);
    // The boundaries: a request ending the day before the period and one starting after it are not in it.
    expect(rows.some((r) => r['Start date'] === day(0) && r['Employee code'] === inFin.code)).toBe(false);
    expect(rows.some((r) => r['Start date'] === day(14))).toBe(false);
    expect(rows.some((r) => r['Start date'] === day(0) && r['Employee code'] === inEng.code)).toBe(true);
    expect(rows.some((r) => r['Start date'] === day(7))).toBe(true);
  });

  it('a reader limited to one department gets that department only, exactly as their list shows it', async () => {
    const limited = await h.actor(A, 'HR_ADMINISTRATOR', { departmentFilter: A.financeDept });
    const { rows } = await generated(limited, 'LEAVE_REGISTER', PERIOD);
    expect(rows.map((r) => r['Employee code'])).toEqual([inFin.code]);
    expect(byKey(rows)).toEqual(byKey(await listed(limited, [inFin])));
    // The same reader's list does not open the people the file leaves out.
    expect((await h.call(limited, 'GET', `/v1/employees/${inEng.id}/leave-requests`)).statusCode).toBe(404);
  });

  it('never carries the leave reason, for a caller without the reason grant or with it', async () => {
    const operational = await h.customActor(A, { scope: 'COMPANY', permissions: ['leave.export.operational', 'leave.read.operational'] });
    const withReason = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['leave.read.reason'] });
    // The fixture is real: the reason is there to be leaked, and the list shows it only to the grant.
    const own = async (a: TestActor) => (await h.call(a, 'GET', `/v1/employees/${inFin.id}/leave-requests`)).json().items as { reason?: string }[];
    expect((await own(withReason))[0]!.reason).toBe(PRIVATE_REASON);
    expect((await own(operational))[0]!.reason).toBeUndefined();
    for (const a of [operational, withReason]) {
      const { rows, body } = await generated(a, 'LEAVE_REGISTER', PERIOD);
      expect(rows.length).toBeGreaterThan(0);
      expect(body).not.toContain('zq7');
    }
  });

  it('stays in its company', async () => {
    const elsewhere = await h.actor(B, 'HR_ADMINISTRATOR');
    expect((await generated(elsewhere, 'LEAVE_REGISTER', PERIOD)).rows).toEqual([]);
  });
});

describe('ATTENDANCE_REGISTER (FR-021; BR-026; ZT17)', () => {
  // Fixed past dates: 2 and 3 March 2026 are a Monday and a Tuesday.
  const MON = '2026-03-02';
  const TUE = '2026-03-03';
  const PERIOD = { from: MON, to: TUE };
  const PRIVATE_REASON = 'Private correction note zq8 (synthetic)';
  let dayShift: string;
  let lateShift: string;
  let branch: string;
  let full: Person;
  let halfDay: Person;
  let finance: Person;

  /** GET /attendance/records as the report's rows: the same filters, under the same actor. */
  async function listed(a: TestActor, filters: Record<string, unknown>) {
    const query = Object.entries({ ...filters, pageSize: 100 }).map(([k, v]) => `${k}=${encodeURIComponent(String(v))}`).join('&');
    const res = await h.call(a, 'GET', `/v1/attendance/records?${query}`);
    expect(res.statusCode, res.body).toBe(200);
    const { items, total } = res.json() as { total: number; items: { employeeCode: string; workDate: string; status: string; workedMinutes: number | null; late: boolean; exceptionCode: string | null; amended: boolean }[] };
    expect(items).toHaveLength(total); // one page holds them all, so the comparison is of everything
    return items.map((r) => ({ 'Employee code': r.employeeCode, 'Work date': r.workDate, Status: r.status, 'Worked minutes': String(r.workedMinutes ?? ''), Late: String(r.late), Exception: r.exceptionCode ?? '', Amended: String(r.amended) }));
  }
  const sorted = (rows: Record<string, string>[]) => [...rows].sort((x, y) => `${x['Employee code']}${x['Work date']}`.localeCompare(`${y['Employee code']}${y['Work date']}`));

  beforeAll(async () => {
    const shift = async (code: string, inTime: string) => (await h.call(hr, 'POST', '/v1/shifts', { code, name: code, inTime, outTime: '18:00', breaks: [] })).json().id as string;
    dayShift = await shift('PARITY_DAY', '09:00');
    lateShift = await shift('PARITY_LATE', '10:00');
    const policy = (await h.call(hr, 'GET', '/v1/attendance/policies')).json().items[0];
    if (policy.state === 'DRAFT') expect((await h.call(hr, 'POST', `/v1/attendance/policies/${policy.id}/activate`, { expectedVersion: policy.version })).statusCode).toBe(200);
    branch = (await h.one<{ id: string }>(`insert into location (company_id, code, name, active) values ($1, 'PARITY_BRANCH', 'Parity branch', true) returning id`, [A.id])).id;
    const worker = async (shiftId: string, over: Record<string, unknown> = {}) => {
      const p = await person(over);
      expect((await h.call(hr, 'POST', `/v1/employees/${p.id}/shift`, { shiftId, effectiveFrom: '2026-01-05' })).statusCode).toBeLessThan(300);
      return p;
    };
    full = await worker(dayShift);
    halfDay = await worker(lateShift, { locationId: branch });
    finance = await worker(dayShift, { departmentId: A.financeDept });
    const punches = (code: string, list: [string, string, 'IN' | 'OUT'][]) =>
      h.call(hr, 'POST', '/v1/attendance/punches', { punches: list.map(([d, t, direction]) => ({ employeeCode: code, occurredAt: `${d}T${t}:00+05:30`, direction, externalEventKey: uniq('parity-evt-') })) });
    expect((await punches(full.code, [[MON, '09:00', 'IN'], [MON, '18:00', 'OUT'], [TUE, '09:00', 'IN'], [TUE, '18:00', 'OUT']])).statusCode).toBeLessThan(300);
    expect((await punches(halfDay.code, [[MON, '10:00', 'IN'], [MON, '14:00', 'OUT']])).statusCode).toBeLessThan(300);
    expect((await punches(finance.code, [[MON, '09:00', 'IN'], [MON, '18:00', 'OUT']])).statusCode).toBeLessThan(300);
    for (const workDate of [MON, TUE]) await h.runBulkJob(hr, '/v1/attendance/processing', { workDate });
    // An amendment, with a reason that must not travel.
    const record = (await h.call(hr, 'GET', `/v1/employees/${finance.id}/attendance?from=${TUE}&to=${TUE}`)).json().items[0];
    const amended = await h.call(hr, 'POST', `/v1/attendance/records/${record.id}/amend`, { expectedVersion: record.version, status: 'PRESENT', reason: PRIVATE_REASON });
    expect(amended.statusCode, amended.body).toBe(200);
  });

  it('holds exactly the list for the period: the same days, statuses, minutes and flags, and the same total minutes', async () => {
    const { rows } = await generated(hr, 'ATTENDANCE_REGISTER', PERIOD);
    expect(sorted(rows)).toEqual(sorted(await listed(hr, PERIOD)));
    const source = await h.one<{ n: number; minutes: number }>(`select count(*)::int as n, coalesce(sum(worked_minutes), 0)::int as minutes from attendance_record where company_id = $1 and work_date between $2::date and $3::date`, [A.id, MON, TUE]);
    expect(rows).toHaveLength(source.n);
    expect(rows.reduce((total, r) => total + Number(r['Worked minutes'] || 0), 0)).toBe(source.minutes);
    expect(rows.find((r) => r['Employee code'] === full.code && r['Work date'] === MON)).toMatchObject({ Status: 'PRESENT', Amended: 'false' });
    expect(rows.find((r) => r['Employee code'] === finance.code && r['Work date'] === TUE)).toMatchObject({ Status: 'PRESENT', Amended: 'true' });
    expect(rows.find((r) => r['Employee code'] === halfDay.code && r['Work date'] === TUE)).toMatchObject({ Amended: 'false' });
    expect(rows.filter((r) => r['Work date']! < MON || r['Work date']! > TUE)).toEqual([]);
    expect((await generated(hr, 'ATTENDANCE_REGISTER', { from: '2026-02-01', to: '2026-02-02' })).rows).toEqual([]);
  });

  it('every declared filter narrows the file exactly as it narrows the list', async () => {
    const whole = (await generated(hr, 'ATTENDANCE_REGISTER', PERIOD)).rows.length;
    const filters: Record<string, unknown>[] = [
      { employeeId: halfDay.id },
      { locationId: branch },
      { departmentId: A.financeDept },
      { shiftId: lateShift },
      { search: full.code },
      { status: 'PRESENT' },
      { minuteField: 'WORKED', minuteOp: 'GTE', minuteValue: 400 },
      { minuteField: 'WORKED', minuteOp: 'LT', minuteValue: 400, employeeId: halfDay.id },
    ];
    for (const f of filters) {
      const label = JSON.stringify(f);
      const { rows } = await generated(hr, 'ATTENDANCE_REGISTER', { ...PERIOD, ...f });
      expect(sorted(rows), label).toEqual(sorted(await listed(hr, { ...PERIOD, ...f })));
      expect(rows.length, label).toBeGreaterThan(0);
      expect(rows.length, label).toBeLessThan(whole);
    }
    expect(await refusal(hr, 'ATTENDANCE_REGISTER', { ...PERIOD, minuteField: 'WORKED', minuteOp: 'GTE' })).toEqual([422, 'MINUTE_FILTER_INCOMPLETE']);
  });

  it('a reader limited to one department gets that department only, as their list does', async () => {
    const limited = await h.actor(A, 'HR_ADMINISTRATOR', { departmentFilter: A.financeDept });
    const { rows } = await generated(limited, 'ATTENDANCE_REGISTER', PERIOD);
    expect(sorted(rows)).toEqual(sorted(await listed(limited, PERIOD)));
    const shown = new Set(rows.map((r) => r['Employee code']));
    expect(shown.has(finance.code)).toBe(true);
    expect(shown.has(full.code)).toBe(false);
    expect(shown.has(halfDay.code)).toBe(false);
    // Everyone the file holds is in that department on the work date, whoever else this company employs.
    const outside = await h.db.query(
      `select e.employee_code from employee e join employment_assignment ea on ea.company_id = e.company_id and ea.employee_id = e.id and ea.effective_from <= $3::date and (ea.effective_to is null or ea.effective_to > $3::date)
        where e.company_id = $1 and e.employee_code = any($2::text[]) and ea.department_id <> $4`,
      [A.id, [...shown], MON, A.financeDept],
    );
    expect(outside.rows).toEqual([]);
  });

  it('never carries an amendment reason or a raw punch', async () => {
    const operational = await h.customActor(A, { scope: 'COMPANY', permissions: ['attendance.export.operational', 'attendance.read.operational'] });
    for (const a of [hr, operational]) {
      const { rows, body } = await generated(a, 'ATTENDANCE_REGISTER', PERIOD);
      expect(rows.length).toBeGreaterThan(0);
      expect(body).not.toContain('zq8');
      expect(body).not.toContain('T03:30');
    }
  });

  it('stays in its company, even asked for another company’s employee', async () => {
    const elsewhere = await h.actor(B, 'HR_ADMINISTRATOR');
    expect((await generated(elsewhere, 'ATTENDANCE_REGISTER', PERIOD)).rows).toEqual([]);
    expect((await generated(elsewhere, 'ATTENDANCE_REGISTER', { ...PERIOD, employeeId: full.id })).rows).toEqual([]);
    expect((await generated(elsewhere, 'ATTENDANCE_REGISTER', { ...PERIOD, shiftId: dayShift })).rows).toEqual([]);
  });
});

describe('CONFIRMATION_DUE scope (FR-093; ZT17; list parity per view is in confirmation.api.test.ts)', () => {
  const PRIVATE_REASON = 'Private cancellation note zq9 (synthetic)';
  let inEng: Person;
  let inFin: Person;
  let cancelled: Person & { caseId: string };

  beforeAll(async () => {
    const boss = await person();
    const probationer = async (over: Record<string, unknown> = {}) => {
      const p = await person(over, 'ACTIVE_PROBATION');
      expect((await h.call(hr, 'POST', `/v1/employees/${p.id}/manager`, { managerEmployeeId: boss.id, effectiveFrom: '2026-01-05' })).statusCode).toBe(200);
      const opened = await h.call(hr, 'POST', '/v1/confirmations', { employeeId: p.id });
      expect(opened.statusCode, opened.body).toBe(201);
      return { ...p, caseId: opened.json().caseId as string };
    };
    inEng = await probationer();
    inFin = await probationer({ departmentId: A.financeDept });
    const toCancel = await probationer();
    cancelled = toCancel;
    const version = (await h.call(hr, 'GET', `/v1/confirmations/${toCancel.caseId}`)).json().version;
    const res = await h.call(hr, 'POST', `/v1/confirmations/${toCancel.caseId}/cancel`, { expectedVersion: version, reason: PRIVATE_REASON });
    expect(res.statusCode, res.body).toBe(200);
  });

  const codes = (rows: Record<string, string>[]) => rows.map((r) => r['Employee code']).sort();
  const listedCodes = async (a: TestActor) => ((await h.call(a, 'GET', '/v1/confirmations?view=ALL')).json().items as { employeeCode: string }[]).map((i) => i.employeeCode).sort();

  it('a reader limited to one department gets that department’s cases only, as their list does', async () => {
    const limited = await h.actor(A, 'HR_ADMINISTRATOR', { departmentFilter: A.financeDept });
    const { rows } = await generated(limited, 'CONFIRMATION_DUE');
    expect(codes(rows)).toEqual(await listedCodes(limited));
    expect(codes(rows)).toEqual([inFin.code]);
    const whole = await generated(hr, 'CONFIRMATION_DUE');
    expect(codes(whole.rows)).toEqual(await listedCodes(hr));
    expect(codes(whole.rows)).toEqual(expect.arrayContaining([inEng.code, inFin.code, cancelled.code]));
  });

  it('never carries the cancellation reason, though the case view shows it to the reason grant', async () => {
    const withReason = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['confirmation.read.reason'] });
    expect((await h.call(withReason, 'GET', `/v1/confirmations/${cancelled.caseId}`)).body).toContain(PRIVATE_REASON);
    const operational = await h.customActor(A, { scope: 'COMPANY', permissions: ['confirmation.export.operational', 'confirmation.read.operational'] });
    for (const a of [hr, withReason, operational]) {
      const { rows, body } = await generated(a, 'CONFIRMATION_DUE');
      expect(rows.length).toBeGreaterThan(0);
      expect(body).not.toContain('zq9');
    }
  });

  it('stays in its company', async () => {
    const elsewhere = await h.actor(B, 'HR_ADMINISTRATOR');
    expect((await generated(elsewhere, 'CONFIRMATION_DUE')).rows).toEqual([]);
  });
});

describe('EXPENSE_REGISTER (FR-079; BR-026; ZT17; DF07)', () => {
  const FINANCE: PermissionKey[] = [
    'expense.read.operational',
    'expense.export.operational',
    'expense.manager_decide.operational',
    'expense.finance_decide.operational',
    'expense.high_value_decide.operational',
    'payment.read.operational',
    'payment.prepare.operational',
    'payment.release.operational',
    'payment.confirm_outcome.operational',
    'payment.reverse.operational',
  ];
  const daysAgo = (n: number) => new Date(Date.now() - n * 86_400_000).toISOString().slice(0, 10);
  const PERIOD = { from: daysAgo(20), to: daysAgo(-1) };
  const SECRET = 'zq6';
  let reader: TestActor;
  let manager: TestActor;
  let fin1: TestActor;
  let fin2: TestActor;
  let fin3: TestActor;
  let employee: TestActor;
  let employeeP: Person;
  let otherDeptP: Person;
  let otherDept: TestActor;
  const claims: Record<string, string> = {};

  const line = async (a: TestActor, category: string, amount: string) => {
    const receipt = (await h.call(a, 'POST', '/v1/expense/receipts', { fileName: 'r.pdf', contentBase64: Buffer.from(`%PDF-1.4\n% synthetic parity receipt ${uniq('r')}\n%%EOF\n`).toString('base64') })).json().receiptId as string;
    return { category, expenseDate: daysAgo(2), merchant: `Merchant ${SECRET}`, grossAmount: amount, claimedAmount: amount, description: `Description ${SECRET} (synthetic)`, receipt: { receiptId: receipt } };
  };
  const drafted = async (a: TestActor, lines: object[]) => {
    const res = await h.call(a, 'POST', '/v1/expense/claims', { purpose: `Purpose ${SECRET} (synthetic)`, currency: 'INR', lines });
    expect(res.statusCode, res.body).toBe(201);
    return res.json().claimId as string;
  };
  const submitted = async (a: TestActor, lines: object[]) => {
    const id = await drafted(a, lines);
    const version = (await h.call(a, 'GET', `/v1/expense/claims/${id}`)).json().version;
    const res = await h.call(a, 'POST', `/v1/expense/claims/${id}/submit`, { expectedVersion: version });
    expect(res.statusCode, res.body).toBe(200);
    return id;
  };
  const decide = async (a: TestActor, claimId: string, body: Record<string, unknown>) => {
    const tx = (await h.one<{ transaction_id: string }>(`select transaction_id from expense_claim where id = $1`, [claimId])).transaction_id;
    const task = ((await h.call(a, 'GET', '/v1/expense/tasks')).json().items as { taskId: string; transactionId: string }[]).find((t) => t.transactionId === tx)!;
    const res = await h.call(a, 'POST', `/v1/expense/tasks/${task.taskId}/decision`, { idempotencyKey: uniq('parity-key-'), ...body });
    expect(res.statusCode, res.body).toBe(200);
  };
  /** Manager, then finance with the given allowed amount per line, in the claim's line order. */
  const approved = async (claimId: string, allowed: string[]) => {
    await decide(manager, claimId, { decision: 'APPROVE' });
    const lines = (await h.call(fin1, 'GET', `/v1/expense/claims/${claimId}`)).json().lines as { id: string }[];
    await decide(fin1, claimId, { decision: 'APPROVE', lines: lines.map((l, i) => ({ lineId: l.id, allowedAmount: allowed[i]!, reason: `Clearance ${SECRET} (synthetic)` })) });
  };
  const prepared = async (claimId: string, amount: string) => {
    const res = await prepareReady(h, fin2, { claimId, amount, paymentDate: daysAgo(0), idempotencyKey: uniq('parity-pay-') });
    expect(res.statusCode, res.body).toBe(201);
    return res.json().instructionId as string;
  };
  const released = async (claimId: string, amount: string) => {
    const pi = await prepared(claimId, amount);
    const res = await releaseNaming(h, fin3, pi);
    expect(res.statusCode, res.body).toBe(200);
    return pi;
  };
  const outcome = async (pi: string, value: 'CONFIRMED' | 'FAILED') => {
    const res = await h.call(fin3, 'POST', `/v1/expense/payments/${pi}/outcome`, { outcome: value, evidenceKey: uniq('parity-evidence-') });
    expect(res.statusCode, res.body).toBe(200);
  };

  beforeAll(async () => {
    const extra = (keys: PermissionKey[], over: Record<string, unknown> = {}) => h.actor(A, 'HR_ADMINISTRATOR', { extra: keys, ...over });
    fin1 = await extra(FINANCE);
    fin2 = await extra(FINANCE);
    fin3 = await extra(FINANCE);
    reader = await extra(['expense.export.operational', 'expense.read.operational', 'payment.read.operational']);
    await h.db.query(`insert into workflow_fallback_reviewer (company_id, kind, user_id, priority, active) values ($1, 'expense_claim', $2, 1, true)`, [A.id, fin1.user]);
    const boss = await person();
    manager = await h.actor(A, 'REPORTING_MANAGER', { employeeId: boss.id });
    employeeP = await person();
    otherDeptP = await person({ departmentId: A.financeDept });
    for (const p of [employeeP, otherDeptP]) expect((await h.call(hr, 'POST', `/v1/employees/${p.id}/manager`, { managerEmployeeId: boss.id, effectiveFrom: '2026-01-05' })).statusCode).toBe(200);
    employee = await h.actor(A, 'EMPLOYEE', { employeeId: employeeP.id });
    otherDept = await h.actor(A, 'EMPLOYEE', { employeeId: otherDeptP.id });
    const policy = (await h.call(hr, 'GET', '/v1/expense/policies')).json().items[0];
    expect((await h.call(hr, 'POST', `/v1/expense/policies/${policy.id}/activate`, { expectedVersion: policy.version })).statusCode).toBe(200);

    // The BRD's worked example (line 5119): lines 600 + 400, approvals 500 + 300, confirmed payment 600.
    claims.example = await submitted(employee, [await line(employee, 'TRAVEL', '600'), await line(employee, 'OTHER', '400')]);
    await approved(claims.example, ['500', '300']);
    await outcome(await released(claims.example, '600'), 'CONFIRMED');
    // Pending in each pending state: never paid.
    claims.prepared = await submitted(employee, [await line(employee, 'OTHER', '100')]);
    await approved(claims.prepared, ['100']);
    await prepared(claims.prepared, '100');
    claims.released = await submitted(employee, [await line(employee, 'OTHER', '120')]);
    await approved(claims.released, ['120']);
    await released(claims.released, '120');
    // Confirmed in full, confirmed then partly reversed, definitively failed.
    claims.paid = await submitted(employee, [await line(employee, 'MEALS', '40')]);
    await approved(claims.paid, ['40']);
    await outcome(await released(claims.paid, '40'), 'CONFIRMED');
    claims.reversed = await submitted(employee, [await line(employee, 'OTHER', '70')]);
    await approved(claims.reversed, ['70']);
    const toReverse = await released(claims.reversed, '70');
    await outcome(toReverse, 'CONFIRMED');
    expect((await h.call(fin3, 'POST', `/v1/expense/payments/${toReverse}/reversal`, { amount: '20', evidenceKey: uniq('parity-reversal-'), reason: `Bank return ${SECRET} (synthetic)` })).statusCode).toBe(200);
    claims.failed = await submitted(employee, [await line(employee, 'OTHER', '30')]);
    await approved(claims.failed, ['30']);
    await outcome(await released(claims.failed, '30'), 'FAILED');
    // A reduced approval, a zero entitlement and the states before any entitlement.
    claims.reduced = await submitted(employee, [await line(employee, 'OTHER', '200')]);
    await approved(claims.reduced, ['150']);
    claims.zero = await submitted(employee, [await line(employee, 'OFFICE_SUPPLIES', '50')]);
    await approved(claims.zero, ['0']);
    claims.waiting = await submitted(employee, [await line(employee, 'OTHER', '60')]);
    claims.atFinance = await submitted(employee, [await line(employee, 'OTHER', '65')]);
    await decide(manager, claims.atFinance, { decision: 'APPROVE' });
    claims.rejected = await submitted(employee, [await line(employee, 'OTHER', '90')]);
    await decide(manager, claims.rejected, { decision: 'REJECT', reason: `Rejection ${SECRET} (synthetic)` });
    claims.withdrawn = await submitted(employee, [await line(employee, 'OTHER', '15')]);
    expect((await h.call(employee, 'POST', `/v1/expense/claims/${claims.withdrawn}/withdraw`)).statusCode).toBe(200);
    claims.draftOnly = await drafted(employee, [await line(employee, 'OTHER', '10')]);
    claims.otherDept = await submitted(otherDept, [await line(otherDept, 'OTHER', '110')]);
    await approved(claims.otherDept, ['110']);
    // Submitted long before the period: still approved and owing, but not this period's.
    claims.old = await submitted(employee, [await line(employee, 'OTHER', '33')]);
    await approved(claims.old, ['33']);
    await h.db.query(`set session_replication_role = replica`);
    try {
      await h.db.query(`update expense_revision set submitted_at = now() - interval '40 days' where claim_id = $1`, [claims.old]);
    } finally {
      await h.db.query(`set session_replication_role = origin`);
    }
  });

  it('shows each claim’s approved, net paid and outstanding, and a pending payment is never paid (BRD line 5119; ZT17)', async () => {
    const { rows } = await generated(reader, 'EXPENSE_REGISTER', PERIOD);
    const row = (key: string) => rows.find((r) => r.Claim === claims[key]);
    const figures = (key: string) => {
      const r = row(key)!;
      return [r.State, r['Claimed total'], r['Approved amount'], r['Net paid'], r.Outstanding, r['Payment state']];
    };
    expect(figures('example')).toEqual(['APPROVED', '1000.00', '800.00', '600.00', '200.00', 'PART_PAID']);
    expect(figures('prepared')).toEqual(['APPROVED', '100.00', '100.00', '0.00', '100.00', 'UNPAID']);
    expect(figures('released')).toEqual(['APPROVED', '120.00', '120.00', '0.00', '120.00', 'UNPAID']);
    expect(figures('paid')).toEqual(['APPROVED', '40.00', '40.00', '40.00', '0.00', 'PAID']);
    expect(figures('reversed')).toEqual(['APPROVED', '70.00', '70.00', '50.00', '20.00', 'PART_PAID']);
    expect(figures('failed')).toEqual(['APPROVED', '30.00', '30.00', '0.00', '30.00', 'UNPAID']);
    expect(figures('reduced')).toEqual(['APPROVED', '200.00', '150.00', '0.00', '150.00', 'UNPAID']);
    expect(figures('zero')).toEqual(['APPROVED', '50.00', '', '', '', 'NO_PAYABLE_AMOUNT']);
    expect(figures('waiting')).toEqual(['MANAGER_PENDING', '60.00', '', '', '', 'NOT_APPLICABLE']);
    expect(figures('atFinance')).toEqual(['FINANCE_PENDING', '65.00', '', '', '', 'NOT_APPLICABLE']);
    expect(figures('rejected')).toEqual(['REJECTED', '90.00', '', '', '', 'NOT_APPLICABLE']);
    // A withdrawn claim was submitted, so it stays in the period's register; a draft never was, and the old claim is another period's.
    expect(row('withdrawn')).toMatchObject({ State: 'WITHDRAWN', 'Claimed total': '15.00' });
    expect(row('draftOnly')).toBeUndefined();
    expect(row('old')).toBeUndefined();
    expect((await generated(reader, 'EXPENSE_REGISTER', { from: daysAgo(60), to: daysAgo(30) })).rows.map((r) => r.Claim)).toEqual([claims.old]);
  });

  it('reconciles row by row with the claim view and the employee’s list, under the same reader', async () => {
    const { rows } = await generated(reader, 'EXPENSE_REGISTER', PERIOD);
    const listed: { id: string; state: string; paymentState: string; currency: string; claimedTotal: string; submittedAt: string | null }[] = [];
    for (const p of [employeeP, otherDeptP]) {
      const res = await h.call(reader, 'GET', `/v1/employees/${p.id}/expense-claims`);
      expect(res.statusCode, res.body).toBe(200);
      listed.push(...res.json().items);
    }
    const eligible = listed.filter((c) => c.submittedAt !== null && c.id !== claims.old).map((c) => c.id).sort();
    expect(rows.map((r) => r.Claim).sort()).toEqual(eligible);
    for (const r of rows) {
      const inList = listed.find((c) => c.id === r.Claim)!;
      expect([r.State, r['Payment state'], r.Currency, r['Claimed total']], r.Claim).toEqual([inList.state, inList.paymentState, inList.currency, inList.claimedTotal]);
      const view = (await h.call(reader, 'GET', `/v1/expense/claims/${r.Claim}`)).json() as { state: string; payment: { approvedAmount: string; netPaid: string; outstanding: string } | null };
      expect(view.state, r.Claim).toBe(r.State);
      expect([r['Approved amount'], r['Net paid'], r.Outstanding], r.Claim).toEqual([money(view.payment?.approvedAmount), money(view.payment?.netPaid), money(view.payment?.outstanding)]);
    }
  });

  it('reconciles with GET /expense/payables, and its totals have no monetary difference from the ledger', async () => {
    const { rows } = await generated(reader, 'EXPENSE_REGISTER', { from: daysAgo(60), to: daysAgo(-1) });
    const payables = (await h.call(reader, 'GET', '/v1/expense/payables')).json().items as { claimId: string; approvedAmount: string; netPaid: string; pending: string; allocatable: string; paymentState: string }[];
    const owing = rows.filter((r) => r['Approved amount'] !== '' && r['Payment state'] !== 'PAID');
    expect(owing.map((r) => r.Claim).sort()).toEqual(payables.map((p) => p.claimId).sort());
    for (const p of payables) {
      const r = owing.find((x) => x.Claim === p.claimId)!;
      expect([r['Approved amount'], r['Net paid'], r['Payment state']], p.claimId).toEqual([p.approvedAmount, p.netPaid, p.paymentState]);
      // What is owed less what is reserved is what may still be allocated: a reservation is outstanding, not paid.
      expect(money(Number(r.Outstanding) - Number(p.pending)), p.claimId).toBe(p.allocatable);
    }
    // BRD line 5119: at most 200 further reservation on the worked example.
    expect(payables.find((p) => p.claimId === claims.example)).toMatchObject({ allocatable: '200.00' });
    expect(payables.find((p) => p.claimId === claims.prepared)).toMatchObject({ pending: '100.00', allocatable: '0.00' });

    const ledger = await h.one<{ n: number; approved: string; paid: string }>(
      `select count(*)::int as n, sum(approved_amount)::numeric(19,2)::text as approved, sum(net_paid)::numeric(19,2)::text as paid from expense_obligation_ledger where company_id = $1`,
      [A.id],
    );
    expect(rows.filter((r) => r['Approved amount'] !== '')).toHaveLength(ledger.n);
    expect(sum(rows.map((r) => r['Approved amount']))).toBe(ledger.approved);
    expect(sum(rows.map((r) => r['Net paid']))).toBe(ledger.paid);
    expect(sum(rows.map((r) => r.Outstanding))).toBe(money(Number(ledger.approved) - Number(ledger.paid)));
    // By hand, from the amounts above: approved 800 + 100 + 120 + 40 + 70 + 30 + 150 + 110 + 33; confirmed net 600 + 40 + 50.
    expect(ledger).toMatchObject({ n: 9, approved: '1453.00', paid: '690.00' });
  });

  it('shows the submission date the period was applied to: the company’s date, not UTC’s (BR-026)', async () => {
    // 20:00 UTC on `utcDay` is 01:30 on the next day in the company's time zone (Asia/Kolkata).
    const utcDay = daysAgo(15);
    const companyDay = daysAgo(14);
    const claimId = await submitted(employee, [await line(employee, 'OTHER', '11')]);
    await h.db.query(`set session_replication_role = replica`);
    try {
      await h.db.query(`update expense_revision set submitted_at = $2::timestamptz where claim_id = $1`, [claimId, `${utcDay}T20:00:00Z`]);
    } finally {
      await h.db.query(`set session_replication_role = origin`);
    }
    const inPeriod = { from: companyDay, to: companyDay };
    for (const code of ['EXPENSE_REGISTER', 'EXPENSE_LINE_REGISTER']) {
      const { rows } = await generated(reader, code, inPeriod);
      expect(rows.map((r) => [r.Claim, r['Submitted at']]), code).toEqual([[claimId, companyDay]]);
      expect((await generated(reader, code, { from: utcDay, to: utcDay })).rows.filter((r) => r.Claim === claimId), code).toEqual([]);
    }
    const withdrawn = await h.call(employee, 'POST', `/v1/expense/claims/${claimId}/withdraw`);
    expect(withdrawn.statusCode, withdrawn.body).toBe(200);
  });

  it('a reader limited to one department gets that department only, with the same figures', async () => {
    const limited = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['expense.export.operational', 'expense.read.operational', 'payment.read.operational'], departmentFilter: A.financeDept });
    const { rows } = await generated(limited, 'EXPENSE_REGISTER', PERIOD);
    expect(rows.map((r) => r.Claim)).toEqual([claims.otherDept]);
    expect(rows[0]).toMatchObject({ 'Employee code': otherDeptP.code, 'Approved amount': '110.00', 'Net paid': '0.00', Outstanding: '110.00' });
    const payables = (await h.call(limited, 'GET', '/v1/expense/payables')).json().items as { claimId: string; netPaid: string }[];
    expect(payables.map((p) => p.claimId)).toEqual([claims.otherDept]);
    expect((await h.call(limited, 'GET', `/v1/employees/${employeeP.id}/expense-claims`)).statusCode).toBe(404);
  });

  it('never carries the purpose, merchant, description, decision or rejection reasons, or a receipt', async () => {
    const withReason = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['expense.export.operational', 'expense.read.operational', 'payment.read.operational', 'expense.read.reason'] });
    for (const a of [reader, withReason]) {
      const { rows, body } = await generated(a, 'EXPENSE_REGISTER', PERIOD);
      expect(rows.length).toBeGreaterThan(0);
      expect(body).not.toContain(SECRET);
      expect(body).not.toContain('PDF');
    }
    // The fixture is real: the same reader's claim view does show the purpose it is entitled to.
    expect((await h.call(reader, 'GET', `/v1/expense/claims/${claims.example}`)).body).toContain(SECRET);
  });

  it('stays in its company', async () => {
    const elsewhere = await h.actor(B, 'HR_ADMINISTRATOR', { extra: ['expense.export.operational', 'expense.read.operational', 'payment.read.operational'] });
    expect((await generated(elsewhere, 'EXPENSE_REGISTER', PERIOD)).rows).toEqual([]);
  });
});

describe('INCREMENT_HISTORY (FR-089; FR-093; BR-026; ZT17; ZT26; ZT03)', () => {
  const FINANCE: PermissionKey[] = ['salary.manage.salary', 'salary.read.salary', 'increment.read.salary', 'increment.history_read.salary', 'increment.propose.salary', 'increment.approve.salary', 'increment.export.salary'];
  const FY2026 = { from: '2026-04-01', to: '2027-03-31' };
  const SECRET = 'zq5';
  let hr1: TestActor;
  let hr2: TestActor;
  let chain: Person;
  let refused: Person;
  let finance: Person;

  const salaried = async (monthly: string, annual: string, over: Record<string, unknown> = {}) => {
    const p = await person(over);
    const res = await h.call(hr1, 'POST', `/v1/employees/${p.id}/salary`, { effectiveFrom: '2026-01-05', monthlyGross: monthly, annualCtc: annual, currency: 'INR' });
    expect(res.statusCode, res.body).toBe(201);
    return p;
  };
  const offCycle = async (employeeId: string, effectiveDate: string, amount: string, counterpart: string, decision: 'APPROVE' | 'REJECT', by: TestActor, decider: TestActor) => {
    const res = await h.call(by, 'POST', '/v1/increment-cases/off-cycle', { employeeId, effectiveDate, proposedAmount: amount, proposedCounterpart: counterpart, reason: `Off-cycle ${SECRET} (synthetic)` });
    expect(res.statusCode, res.body).toBe(201);
    const task = ((await h.call(decider, 'GET', '/v1/increment-cases/tasks/mine')).json().items as { taskId: string; ownerEmployeeId: string }[]).find((t) => t.ownerEmployeeId === employeeId)!;
    const decided = await h.call(decider, 'POST', `/v1/increment-cases/tasks/${task.taskId}/decision`, { decision, reason: `Independent review ${SECRET} (synthetic)`, idempotencyKey: uniq('parity-inc-') });
    expect(decided.statusCode, decided.body).toBe(200);
  };
  /** GET /employees/:id/increment-history as the report's rows; what a correction retired is not in force. */
  const listed = async (a: TestActor, p: Person) => {
    const res = await h.call(a, 'GET', `/v1/employees/${p.id}/increment-history`);
    expect(res.statusCode, res.body).toBe(200);
    const items = res.json().items as { effectiveDate: string; basis: string; currency: string; beforeAmount: string; afterAmount: string; changePercent: string | null; percentNaReason: string | null; supersededByHistoryId: string | null }[];
    return items
      .filter((i) => i.supersededByHistoryId === null && i.effectiveDate >= FY2026.from && i.effectiveDate <= FY2026.to)
      .map((i) => ({ 'Employee code': p.code, 'Effective date': i.effectiveDate, Basis: i.basis, Currency: i.currency, Before: money(i.beforeAmount), After: money(i.afterAmount), 'Change %': i.changePercent ?? '', 'N/A reason': i.percentNaReason ?? '' }));
  };

  beforeAll(async () => {
    hr1 = await h.actor(A, 'HR_ADMINISTRATOR', { extra: FINANCE });
    hr2 = await h.actor(A, 'HR_ADMINISTRATOR', { extra: FINANCE });
    await h.db.query(`insert into workflow_fallback_reviewer (company_id, kind, user_id, priority, active) values ($1, 'increment_case', $2, 1, true), ($1, 'increment_case', $3, 2, true)`, [A.id, hr1.user, hr2.user]);
    chain = await salaried('100000', '1200000');
    refused = await salaried('50000', '600000');
    finance = await salaried('90000', '1080000', { departmentId: A.financeDept });
    // ZT26: 100000 -> 110000 -> 121000 is two 10 percent changes.
    await offCycle(chain.id, '2026-07-01', '110000', '1320000', 'APPROVE', hr1, hr2);
    await offCycle(chain.id, '2027-01-01', '121000', '1452000', 'APPROVE', hr2, hr1);
    await offCycle(refused.id, '2026-09-01', '55000', '660000', 'REJECT', hr1, hr2);
    await offCycle(finance.id, '2026-10-01', '99000', '1188000', 'APPROVE', hr1, hr2);
  });

  it('holds exactly the applied history of the period, with the list’s amounts and percentages (ZT26)', async () => {
    const { rows } = await generated(hr1, 'INCREMENT_HISTORY', FY2026);
    const expected = [...(await listed(hr1, chain)), ...(await listed(hr1, finance)), ...(await listed(hr1, refused))];
    expect(expected.length).toBeGreaterThan(0);
    const key = (r: Record<string, string>) => `${r['Employee code']}${r['Effective date']}${r.Basis}`;
    expect(rows.filter((r) => [chain.code, finance.code, refused.code].includes(r['Employee code']!)).sort((x, y) => key(x).localeCompare(key(y)))).toEqual(expected.sort((x, y) => key(x).localeCompare(key(y))));
    const own = rows.filter((r) => r['Employee code'] === chain.code);
    expect(own.map((r) => [r['Effective date'], r.Before, r.After, r['Change %']])).toEqual([
      ['2026-07-01', '100000.00', '110000.00', '10.00'],
      ['2027-01-01', '110000.00', '121000.00', '10.00'],
    ]);
    // A rejected increase is no part of the history.
    expect(rows.some((r) => r['Employee code'] === refused.code)).toBe(false);
    // The period applies: the second change is outside a calendar 2026 file.
    const calendar = await generated(hr1, 'INCREMENT_HISTORY', { from: '2026-01-01', to: '2026-12-31' });
    expect(calendar.rows.filter((r) => r['Employee code'] === chain.code).map((r) => r['Effective date'])).toEqual(['2026-07-01']);
    // The file's money is the history's money, to the rupee and paisa.
    const source = await h.one<{ after: string }>(`select sum(after_amount)::numeric(19,2)::text as after from increment_history_in_force where company_id = $1 and effective_date between $2::date and $3::date`, [A.id, FY2026.from, FY2026.to]);
    expect(sum(rows.map((r) => r.After))).toBe(source.after);
  });

  it('a reader limited to one department gets that department only, as their history route does', async () => {
    const limited = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['increment.read.salary', 'increment.history_read.salary', 'increment.export.salary'], departmentFilter: A.financeDept });
    const { rows } = await generated(limited, 'INCREMENT_HISTORY', FY2026);
    expect(rows).toEqual(await listed(limited, finance));
    expect(new Set(rows.map((r) => r['Employee code']))).toEqual(new Set([finance.code]));
    expect((await h.call(limited, 'GET', `/v1/employees/${chain.id}/increment-history`)).statusCode).toBe(404);
  });

  it('without the salary export grant nothing is queued or generated; with it the approver’s reason still stays out (DF02)', async () => {
    const queued = async () => (await h.one<{ n: number }>(`select count(*)::int as n from report_execution where company_id = $1 and report_code = 'INCREMENT_HISTORY'`, [A.id])).n;
    const before = await queued();
    expect(await refusal(hr, 'INCREMENT_HISTORY', FY2026)).toEqual([403, 'FORBIDDEN']);
    const readOnly = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['increment.read.salary', 'increment.history_read.salary'] });
    expect(await refusal(readOnly, 'INCREMENT_HISTORY', FY2026)).toEqual([403, 'FORBIDDEN']);
    expect(await queued()).toBe(before);

    const withReason = await h.actor(A, 'HR_ADMINISTRATOR', { extra: ['increment.history_read.salary', 'increment.export.salary', 'increment.read.reason'] });
    expect((await h.call(withReason, 'GET', `/v1/employees/${chain.id}/increment-history`)).body).toContain(SECRET);
    for (const a of [hr1, withReason]) {
      const { rows, body } = await generated(a, 'INCREMENT_HISTORY', FY2026);
      expect(rows.length).toBeGreaterThan(0);
      expect(body).not.toContain(SECRET);
    }
  });

  it('stays in its company', async () => {
    const elsewhere = await h.actor(B, 'HR_ADMINISTRATOR', { extra: ['increment.read.salary', 'increment.history_read.salary', 'increment.export.salary'] });
    expect((await generated(elsewhere, 'INCREMENT_HISTORY', FY2026)).rows).toEqual([]);
  });
});
